{
  "artefact_id": "adr-auth-clerk-023",
  "owner": "Ruslan Faion <ruslan@faion.net>",
  "version": "1.0.0",
  "last_reviewed": "2026-05-23",
  "adr_id": "023",
  "title": "Adopt Clerk for identity",
  "status": "Accepted",
  "date": "2026-05-23",
  "context": "Auth0 pricing climbed; we need an alternative with SSO and decent UX.",
  "decision": "Adopt Clerk as the primary identity provider for new signups.",
  "consequences": {
    "positive": ["Cheaper at current MAU", "SSO ships without custom work"],
    "negative": ["Vendor concentration on Clerk", "Migration cost if pricing moves again"]
  },
  "alternatives_rejected": [
    {
      "option": "WorkOS",
      "reason": "Higher floor cost"
    },
    {
      "option": "Stay on Auth0",
      "reason": "The pricing climb is the reason for the ADR"
    }
  ],
  "supersedes": null,
  "superseded_by": null
}
